            aIngress = (RotL64(aEarthLaneA[((aIndex + 2337U)) & S_BLOCK1], 47U) ^ RotL64(aEarthLaneB[((aIndex + 3491U)) & S_BLOCK1], 13U));
            aIngress ^= RotL64(aKeyRowReadB[(((2047U - aIndex) + 892U)) & W_KEY1], 58U);
