            aCross ^= RotL64(pSnowLaneA[((S_BLOCK1 - aIndex + 3180U)) & S_BLOCK1], 57U);
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aIngress, 39U) + RotL64(aCarry, 52U)) + (RotL64(aCross, 23U) ^ RotL64(aPrevious, 11U));
            aScatter = TwistMix64::DiffuseA(aScatter);
            //
            aOrbiterA = ((aWandererG + RotL64(aIngress, 5U)) + 0xC2D34BEA40549771ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterD = (aWandererF + RotL64(aScatter, 30U)) + 0xD78B0B2FE248305AULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 37U)) + RotL64(aCarry, 41U)) + 0xDC8EA957F09992BBULL;
            aOrbiterC = (aWandererA + RotL64(aPrevious, 13U)) + 0x0D9B21E56CEE9D8FULL;
            aOrbiterK = (((aWandererC + RotL64(aScatter, 51U)) + RotL64(aCarry, 19U)) + 0x1614211CFCC62B2CULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 12U)) & S_SALT1];
            aOrbiterF = ((aWandererK + RotL64(aIngress, 21U)) + RotL64(aCarry, 53U)) + 0x633211CBBED480CFULL;
            aOrbiterH = (aWandererE + RotL64(aCross, 43U)) + 0x48CC174D5ED75C38ULL;
            //
            aOrbiterA = ((aOrbiterA + aOrbiterD) + 0x10FA338AC30BD2AAULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 14U)) & S_SALT1];
