            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0xAC376BF3A88A3869ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x5A7725BE86043099ULL), 47U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterA) + 0xF9C63667C0B406E6ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 5U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterK) ^ 0x3543AF0D568C86F9ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3DDEAF2AF8B63BF3ULL), 19U);
