            //
            aWandererK = aWandererK ^ (((RotL64(aPrevious, 60U) + RotL64(aOrbiterB, 37U)) + aOrbiterH) + aTwistWandererUpdateSaltE[((aIndex + 13U)) & S_SALT1]);
            aWandererC = aWandererC + (((RotL64(aScatter, 3U) + aOrbiterC) + RotL64(aOrbiterD, 5U)) + RotL64(aCarry, 3U));
            aWandererF = aWandererF ^ ((RotL64(aIngress, 21U) + aOrbiterD) + RotL64(aOrbiterB, 21U));
            aWandererE = aWandererE + ((RotL64(aCross, 43U) + RotL64(aOrbiterA, 57U)) + aOrbiterK);
            aWandererG = aWandererG ^ (((RotL64(aIngress, 11U) + RotL64(aOrbiterF, 11U)) + aOrbiterK) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 9U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 53U) + RotL64(aOrbiterH, 48U)) + aOrbiterD) + RotL64(aCarry, 43U));
            aWandererA = aWandererA ^ ((RotL64(aPrevious, 37U) + aOrbiterF) + RotL64(aOrbiterH, 29U));
