            aOrbiterI = ((aWandererD + RotL64(aPrevious, 19U)) + RotL64(aCarry, 27U)) + 0x496FD30F9497F1BCULL;
            aOrbiterK = ((aWandererH + RotL64(aCross, 13U)) + RotL64(aCarry, 53U)) + 0x0BF5F41E91DE1F6BULL;
            aOrbiterJ = (aWandererJ + RotL64(aScatter, 28U)) + 0x8D985DC556D9EE8CULL;
            aOrbiterE = ((aWandererG + RotL64(aIngress, 5U)) + RotL64(aCarry, 3U)) + 0x6B56BDF5267625B8ULL;
            aOrbiterH = ((aWandererF + RotL64(aScatter, 47U)) + 0xFA360A7C9C951AD5ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterB = ((aWandererB + RotL64(aCross, 41U)) + 0x1AF935D7B76292E1ULL) + aTwistOrbiterAssignSaltD[((aIndex + 3U)) & S_SALT1];
            aOrbiterC = (aWandererE + RotL64(aPrevious, 53U)) + 0x3A7E6BA3F189C099ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0x7382E90E6AC72FCEULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterI) ^ 0x993B7F50631633B2ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x09A60390430F419DULL), 43U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterJ) + 0xD8D12FB1E8D76395ULL) + aTwistOrbiterUpdateSaltD[((aIndex + 21U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0xB108A9A09E877CF3ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xC06C9E88667A3033ULL), 19U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0x490C17D4FB629A3DULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterK) ^ 0xBE34AA7CC1857365ULL) ^ aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x37014218FD5B9DD5ULL), 35U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0x10F1A874C75E3D19ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterH) ^ 0xC43E2E5D0D623CA2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x1B18A8415087015FULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x6222C9C34F3BC488ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterB) ^ 0x3779344C9342152CULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 7U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xF65C110109AFA8CDULL), 13U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterB) + 0x5A259C8C313FB4DBULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0xCB1D15C2E81A4212ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x6DEC5DB131F03D65ULL), 53U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterI) + 0x414C34DCD118980DULL) + aTwistOrbiterUpdateSaltC[((aIndex + 25U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x72702CDB182FA9CBULL;
            aOrbiterE = RotL64((aOrbiterE * 0x1DCD46B85CC280D1ULL), 27U);
            //
            aIngress = RotL64(aOrbiterC, 35U) ^ aOrbiterB;
            aIngress = aIngress + (aOrbiterH ^ RotL64(aOrbiterK, 23U));
            aIngress = aIngress + (RotL64(aOrbiterI, 29U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterE, 56U);
