            //
            aWandererG = aWandererG + (((RotL64(aScatter, 53U) + RotL64(aOrbiterC, 13U)) + aOrbiterH) + RotL64(aCarry, 41U));
            aWandererJ = aWandererJ ^ ((RotL64(aPrevious, 35U) + RotL64(aOrbiterH, 5U)) + aOrbiterK);
            aWandererE = aWandererE + (((RotL64(aCross, 43U) + RotL64(aOrbiterC, 58U)) + aOrbiterE) + RotL64(aCarry, 29U));
            aWandererF = aWandererF ^ (((RotL64(aIngress, 27U) + aOrbiterJ) + RotL64(aOrbiterB, 41U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 28U)) & S_SALT1]);
