            aWandererD = aWandererD ^ (((RotL64(aPrevious, 3U) + aOrbiterI) + RotL64(aOrbiterJ, 3U)) + aTwistWandererUpdateSaltB[(((31U - aIndex) + 13U)) & S_SALT1]);
