            //
            aOrbiterF = ((aWandererG + RotL64(aCross, 37U)) + RotL64(aCarry, 37U)) + 0x0B18AC9C4D3C4BDBULL;
            aOrbiterG = (aWandererK + RotL64(aPrevious, 11U)) + 0xD2AA2CF0238ACA33ULL;
            aOrbiterC = ((aWandererJ + RotL64(aIngress, 60U)) + RotL64(aCarry, 53U)) + 0x2472A4AE18F07C72ULL;
            aOrbiterJ = (aWandererD + RotL64(aScatter, 5U)) + 0xCA43C63366DBCA56ULL;
            aOrbiterB = ((aWandererF + RotL64(aCross, 29U)) + 0x323186E320E12261ULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterK = (aWandererI + RotL64(aPrevious, 21U)) + 0x17233E129599CE03ULL;
            aOrbiterI = (((aWandererB + RotL64(aScatter, 43U)) + RotL64(aCarry, 3U)) + 0xD0DA8C961415F368ULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 3U)) & S_SALT1];
            //
            aOrbiterF = (aOrbiterF + aOrbiterG) + 0x77D096DDD1D5714AULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterF) ^ 0x509D53DB8FED2EF5ULL;
