            aOrbiterG = ((aOrbiterG + aOrbiterJ) + 0xEE03A411F698BC88ULL) + aTwistOrbiterUpdateSaltF[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0x9C7CD8CA79FB9049ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x1A0B4B32FAB475C5ULL), 57U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterF) + 0x7C794B7CFC3D190AULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0x1194B7485558C9B7ULL) ^ aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x40AA9BD17C7C2119ULL), 23U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x73BBB23386FAD2BEULL;
