            aCross = (RotL64(aFuseLaneA[((S_BLOCK1 - aIndex + 20710U)) & S_BLOCK1], 60U) ^ RotL64(aWaterLaneB[((S_BLOCK1 - aIndex + 22363U)) & S_BLOCK1], 29U));
