            //
            aOrbiterE = ((aWandererF + RotL64(aScatter, 35U)) + RotL64(aCarry, 13U)) + 0x1F2FBE0FC6BEFC56ULL;
            aOrbiterG = (aWandererE + RotL64(aPrevious, 57U)) + 0x6D852D5429ED51CFULL;
            aOrbiterB = (aWandererB + RotL64(aIngress, 27U)) + 0x4C4D7EA5DB46E08DULL;
            aOrbiterH = (((aWandererI + RotL64(aCross, 48U)) + RotL64(aCarry, 35U)) + 0x935ED1BA0926E65EULL) + aTwistOrbiterAssignSaltB[((aIndex + 7U)) & S_SALT1];
            aOrbiterJ = (aWandererJ + RotL64(aScatter, 11U)) + 0xB82F33F8542B73E8ULL;
            aOrbiterC = (((aWandererK + RotL64(aIngress, 3U)) + RotL64(aCarry, 47U)) + 0xDB3B08C61C5504B5ULL) + aTwistOrbiterAssignSaltA[((aIndex + 22U)) & S_SALT1];
            aOrbiterK = (aWandererC + RotL64(aPrevious, 19U)) + 0x4C6D2BC9EC203F2FULL;
            //
            aOrbiterE = (aOrbiterE + aOrbiterG) + 0x90BA1CAFA7519F67ULL;
            aOrbiterB = ((aOrbiterB ^ aOrbiterE) ^ 0x1A2F39C41E3E3C31ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterB = RotL64((aOrbiterB * 0x9B11474CACE42703ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterJ) + 0x2EE2DDACB63DA523ULL;
