            aOrbiterC = RotL64((aOrbiterC * 0x2D3D0A59F482157BULL), 3U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0xA5C06D0EC9589C7BULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterJ) ^ 0xC0AE1FBC95FBDB11ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x9847AF1D353585F9ULL), 21U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterE) + 0x2E35476B643D10D3ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterC) ^ 0xF0575A11EB5C3999ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x596FAE3F96CA4D3FULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterK) + 0xCD5E81AE0E2CDA9CULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x9F5961702ACA18EEULL;
            aOrbiterH = RotL64((aOrbiterH * 0x12C6022EA850E1B5ULL), 41U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0xC7E5BA75E7E971C7ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterG) ^ 0xC67623D6397297B2ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 8U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x68FC99F886E7DA69ULL), 51U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x1E3833EABA095846ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x0A6EFDDAC2DC54ABULL;
