            //
            aWandererE = aWandererE ^ (((RotL64(aPrevious, 53U) + aOrbiterG) + RotL64(aOrbiterB, 13U)) + aTwistWandererUpdateSaltC[((aIndex + 17U)) & S_SALT1]);
            aWandererF = aWandererF + (((RotL64(aIngress, 5U) + aOrbiterE) + RotL64(aOrbiterJ, 41U)) + RotL64(aCarry, 27U));
            aWandererJ = aWandererJ ^ (((RotL64(aCross, 23U) + aOrbiterJ) + RotL64(aOrbiterB, 35U)) + aTwistWandererUpdateSaltF[(((31U - aIndex) + 23U)) & S_SALT1]);
            aWandererK = aWandererK + ((RotL64(aScatter, 44U) + aOrbiterK) + RotL64(aOrbiterH, 3U));
