            aOrbiterA = ((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 43U)) + 0x4AA07D83E80F1D39ULL;
            aOrbiterH = (((aWandererB + RotL64(aPrevious, 21U)) + RotL64(aCarry, 27U)) + 0x79B3E56C8C90FD21ULL) + aTwistOrbiterAssignSaltD[(((31U - aIndex) + 4U)) & S_SALT1];
            aOrbiterK = (aWandererK + RotL64(aScatter, 29U)) + 0xBDF1B6734FB5697EULL;
            aOrbiterD = ((aWandererF + RotL64(aPrevious, 11U)) + 0xD8E7B581BF3310E0ULL) + aTwistOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterG = (aWandererE + RotL64(aIngress, 60U)) + 0xE3CC75DDF9F4F63AULL;
