            aOrbiterK = RotL64((aOrbiterK * 0x7688D2E182CF36E3ULL), 11U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x905442F4E76BD3CDULL) + aTwistOrbiterUpdateSaltE[((aIndex + 11U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x1A70C3848659DF6CULL;
