            aOrbiterD = (aOrbiterD + aOrbiterG) + 0x0BCF2E8266AB22EAULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xB38312E86A5B15A1ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xE16A9DD1331D14F1ULL), 53U);
