            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x82FC2AE2D492AAECULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterG = (aOrbiterG ^ aOrbiterK) ^ 0xE318CF728E0E6EEEULL;
            aOrbiterG = RotL64((aOrbiterG * 0x371712EEA5887EFBULL), 43U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0xBCD4D3E7393B9036ULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 8U)) & S_SALT1];
