            aWandererA = aWandererA ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterI, 13U)) + aOrbiterA);
            aWandererG = aWandererG + (((RotL64(aCross, 35U) + RotL64(aOrbiterI, 54U)) + aOrbiterG) + RotL64(aCarry, 51U));
