            aOrbiterH = ((aWandererC + RotL64(aPrevious, 37U)) + 0xDB8E7B52B9B77BF9ULL) + aTwistOrbiterAssignSaltC[((aIndex + 25U)) & S_SALT1];
            aOrbiterD = (aWandererH + RotL64(aCross, 39U)) + 0xAC0FD68A31BEED33ULL;
