            aOrbiterJ = RotL64((aOrbiterJ * 0xDDE6165BED6571DDULL), 21U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterI) + 0x43182B6274CB87C2ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterJ) ^ 0xA756D1E190E46CDDULL;
            aOrbiterA = RotL64((aOrbiterA * 0x06DFD0F658F46117ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0xB633E1D325689B20ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0x87AAA83EFD444740ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD0167B465B523979ULL), 51U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0x256A783D9377BE32ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterF) ^ 0x1CDDA78CF912FAB5ULL;
            aOrbiterH = RotL64((aOrbiterH * 0xF728B6F72B8F0E91ULL), 39U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterG) + 0x5CAE7B1B40A835BDULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x9F6DB61335CECE0CULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x82E2CF2F13F53A71ULL), 47U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterK) + 0xBCA579B57D322570ULL;
