            aOrbiterE = RotL64((aOrbiterE * 0x30CDAC426B931321ULL), 41U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterE) + 0x0A2B7D3BCAC23971ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 10U)) & S_SALT1];
