            //
            aOrbiterD = (aOrbiterD + aOrbiterB) + 0x0A7595778C405956ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterD) ^ 0xC2999BC686C16B20ULL;
            aOrbiterI = RotL64((aOrbiterI * 0xF48BCF0AAAE1ED27ULL), 43U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterH) + 0x54461ABAE3AB9A16ULL;
