        //
        // Ingress:
        //      aFuseLaneA (-->), aIceLaneC (-->), aLightningLaneD (-->), aFireLaneA (<-?->)
        //
        // Cross:
        //      aIceLaneA (<--), aIceLaneD (<--), aHeartLaneB (<--), aSoilLaneD (<-?->)
        //
