            aOrbiterK = (((aWandererJ + RotL64(aPrevious, 10U)) + RotL64(aCarry, 3U)) + 0x6F4811A28761B82BULL) + aTwistOrbiterAssignSaltF[(((31U - aIndex) + 12U)) & S_SALT1];
