            aOrbiterJ = (aWandererK + RotL64(aIngress, 19U)) + 0xA234CDBC464A1FABULL;
            aOrbiterK = ((aWandererC + RotL64(aScatter, 28U)) + RotL64(aCarry, 23U)) + 0xD6A2707EEA70DD7DULL;
            aOrbiterF = (((aWandererI + RotL64(aPrevious, 3U)) + RotL64(aCarry, 11U)) + 0x19CE082BEEBE40F5ULL) + aTwistOrbiterAssignSaltE[(((31U - aIndex) + 27U)) & S_SALT1];
            aOrbiterE = ((aWandererA + RotL64(aCross, 43U)) + RotL64(aCarry, 51U)) + 0x8B10F0C559C53795ULL;
            aOrbiterB = (aWandererG + RotL64(aIngress, 13U)) + 0xB705B2BDDF5CE951ULL;
            aOrbiterC = ((aWandererF + RotL64(aPrevious, 57U)) + 0x75B2187E51455C9DULL) + aTwistOrbiterAssignSaltB[(((31U - aIndex) + 9U)) & S_SALT1];
            //
            aOrbiterA = (aOrbiterA + aOrbiterJ) + 0xA8D8086C50334191ULL;
