            aOrbiterD = (aOrbiterD + aOrbiterJ) + 0x49720460E9D629BEULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterD) ^ 0xCC27D628265419E2ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 7U)) & S_SALT1];
