            aOrbiterC = (aOrbiterC + aOrbiterK) + 0x66433F645DC2BCB1ULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterC) ^ 0x7BF4D649F6D6A5F9ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 26U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x57C29CE3334735B5ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0x773ABD5451F81BAFULL) + aTwistOrbiterUpdateSaltC[((aIndex + 20U)) & S_SALT1];
