            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x9C475037C96974DAULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterH) ^ 0x9106B2EA0478808EULL) ^ aTwistOrbiterUpdateSaltB[(((31U - aIndex) + 27U)) & S_SALT1];
