            aOrbiterF = (((aWandererK + RotL64(aScatter, 53U)) + RotL64(aCarry, 35U)) + 0x48231E9E716E76D2ULL) + aTwistOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
