            aOrbiterH = ((aWandererF + RotL64(aPrevious, 19U)) + RotL64(aCarry, 57U)) + 0x5ACB0EA05F2F7C6EULL;
            aOrbiterB = (aWandererB + RotL64(aIngress, 11U)) + 0x2945EEBD7E31816AULL;
            aOrbiterK = (aWandererI + RotL64(aCross, 57U)) + 0x94B2435796C976EFULL;
            aOrbiterE = ((aWandererA + RotL64(aScatter, 6U)) + 0x1873632DA12D9F96ULL) + aTwistOrbiterAssignSaltD[((aIndex + 6U)) & S_SALT1];
            aOrbiterI = (aWandererE + RotL64(aCross, 41U)) + 0x575DC82A6EDF22E5ULL;
            //
            aOrbiterA = (aOrbiterA + aOrbiterC) + 0x29EF65517AF68BCAULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterA) ^ 0x52076840F92CF732ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 21U)) & S_SALT1];
