            //
            aOrbiterB = (((aWandererH + RotL64(aScatter, 13U)) + RotL64(aCarry, 57U)) + 0x52B04C37D464DC6CULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 17U)) & S_SALT1];
            aOrbiterH = (aWandererE + RotL64(aPrevious, 50U)) + 0x513B920BC7F79532ULL;
            aOrbiterK = ((aWandererD + RotL64(aCross, 23U)) + 0x513D21FB5DD0C636ULL) + aKeyRotateOrbiterAssignSaltF[((aIndex + 24U)) & S_SALT1];
