            aCross = (RotL64(aPoisonLaneA[((S_BLOCK1 - aIndex + 10867U)) & S_BLOCK1], 52U) ^ RotL64(aPoisonLaneD[((S_BLOCK1 - aIndex + 13390U)) & S_BLOCK1], 41U));
            aCross ^= (RotL64(aKeyRowReadA[(((2047U - aIndex) + 15018U)) & W_KEY1], 5U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 15280U)) & S_BLOCK1], 21U));
            aCross = TwistMix64::DiffuseA(aCross);
            //
            aScatter = (RotL64(aCarry, 41U) + RotL64(aIngress, 5U)) + (RotL64(aPrevious, 20U) ^ RotL64(aCross, 57U));
            aScatter = TwistMix64::DiffuseB(aScatter);
            //
            aOrbiterF = (aWandererK + RotL64(aPrevious, 5U)) + 0xB8CAD625AD7D6FB5ULL;
            aOrbiterB = (aWandererH + RotL64(aScatter, 51U)) + 0xF60B4C4B2EE3D5CDULL;
            aOrbiterJ = ((aWandererF + RotL64(aIngress, 21U)) + RotL64(aCarry, 23U)) + 0xDDAEB0EAE93F6021ULL;
            aOrbiterH = ((aWandererC + RotL64(aCross, 11U)) + 0xB2552F46A7935458ULL) + aKeyRotateOrbiterAssignSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterC = (aWandererI + RotL64(aIngress, 43U)) + 0x3C9203BFA9A7E59AULL;
            aOrbiterD = (((aWandererG + RotL64(aPrevious, 28U)) + RotL64(aCarry, 11U)) + 0x45E385D63C36681BULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterA = ((aWandererJ + RotL64(aScatter, 35U)) + RotL64(aCarry, 47U)) + 0xBA2CF3CDF0A10835ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x9CDA70D77236FA0FULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterF) ^ 0xDE8F34D6FDC5CC76ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x545E8FCF94619333ULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0xC1764A63A1481B3BULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterJ) ^ 0x9EE3A1702DECE46AULL;
            aOrbiterC = RotL64((aOrbiterC * 0x7D889EDAE33A6DFDULL), 39U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterD) + 0x70754DB939AB0BA6ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterH) ^ 0x5F25870AE1EEB5AFULL;
            aOrbiterF = RotL64((aOrbiterF * 0x906BB098F3D5A455ULL), 29U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x84DBB5BBD29E570AULL) + aKeyRotateOrbiterUpdateSaltF[((aIndex + 16U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x79F19316385193CEULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBB40AC1CD344FE83ULL), 57U);
            //
            aOrbiterC = ((aOrbiterC + aOrbiterF) + 0xB78949B6204AA96CULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 26U)) & S_SALT1];
            aOrbiterA = (aOrbiterA ^ aOrbiterC) ^ 0x769167A7902D02EFULL;
            aOrbiterA = RotL64((aOrbiterA * 0x270B50C84520C159ULL), 11U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterA) + 0x0A6A866686E9114BULL) + aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0xCE4EAEB8E3739E40ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x82F1A777B05222CFULL), 3U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0x9BA76AE69A319FA8ULL) + aKeyRotateOrbiterUpdateSaltE[((aIndex + 23U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x6724C479BF19EA03ULL;
            aOrbiterB = RotL64((aOrbiterB * 0xE5079F938210B3DDULL), 19U);
            //
            aIngress = aOrbiterD ^ RotL64(aOrbiterJ, 19U);
