            //
            aWandererI = aWandererI ^ ((RotL64(aPrevious, 13U) + aOrbiterJ) + RotL64(aOrbiterF, 50U));
            aWandererJ = aWandererJ + ((((RotL64(aScatter, 60U) + aOrbiterD) + RotL64(aOrbiterB, 43U)) + RotL64(aCarry, 47U)) + aKeyRotateWandererUpdateSaltA[(((31U - aIndex) + 8U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aCross, 19U) + aOrbiterJ) + RotL64(aOrbiterA, 27U));
