            aWandererC = aWandererC ^ ((RotL64(aScatter, 35U) + RotL64(aOrbiterH, 13U)) + aOrbiterJ);
            aWandererH = aWandererH + ((((RotL64(aIngress, 51U) + aOrbiterH) + RotL64(aOrbiterB, 57U)) + RotL64(aCarry, 23U)) + aKeyRotateWandererUpdateSaltC[(((31U - aIndex) + 6U)) & S_SALT1]);
            aWandererK = aWandererK ^ ((RotL64(aPrevious, 27U) + RotL64(aOrbiterA, 3U)) + aOrbiterB);
            //
            aCarry = aCarry + (aWandererH ^ RotL64(aWandererG, 42U));
            aCarry = aCarry + (RotL64(aWandererI, 27U) ^ aWandererJ);
