            aIngress = TwistMix64::DiffuseA((aIngress + aScatter));
            //
            aWandererH = aWandererH + ((RotL64(aIngress, 11U) + aOrbiterB) + RotL64(aOrbiterK, 43U));
            aWandererK = aWandererK ^ (((RotL64(aScatter, 35U) + aOrbiterA) + RotL64(aOrbiterJ, 51U)) + aKeyRotateWandererUpdateSaltF[(((31U - aIndex) + 18U)) & S_SALT1]);
            aWandererJ = aWandererJ + (((RotL64(aPrevious, 3U) + RotL64(aOrbiterD, 41U)) + aOrbiterB) + RotL64(aCarry, 19U));
            aWandererE = aWandererE ^ ((RotL64(aCross, 26U) + RotL64(aOrbiterI, 56U)) + aOrbiterE);
            aWandererF = aWandererF + ((RotL64(aPrevious, 19U) + aOrbiterE) + RotL64(aOrbiterJ, 53U));
            aWandererI = aWandererI ^ ((RotL64(aIngress, 43U) + RotL64(aOrbiterA, 23U)) + aOrbiterH);
