            aWandererD = aWandererD ^ ((RotL64(aCross, 41U) + RotL64(aOrbiterG, 13U)) + aOrbiterA);
            aWandererG = aWandererG + ((RotL64(aScatter, 47U) + aOrbiterA) + RotL64(aOrbiterF, 26U));
            aWandererB = aWandererB ^ ((RotL64(aCross, 23U) + RotL64(aOrbiterB, 29U)) + aOrbiterI);
            aWandererC = aWandererC + ((RotL64(aIngress, 30U) + RotL64(aOrbiterA, 35U)) + aOrbiterD);
            //
            aCarry = aCarry + (aWandererB ^ RotL64(aWandererC, 19U));
