            aOrbiterG = (aWandererG + RotL64(aCross, 11U)) + 0xCB0670F426916DA7ULL;
            aOrbiterE = ((aWandererI + RotL64(aIngress, 13U)) + RotL64(aCarry, 27U)) + 0x8BE523D1148EB1CDULL;
            aOrbiterC = (aWandererH + RotL64(aPrevious, 36U)) + 0xB790E5EDDB77345CULL;
            aOrbiterD = ((aWandererC + RotL64(aScatter, 5U)) + 0x87A3B9A20D1CE645ULL) + aKeyRotateOrbiterAssignSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterB = (aWandererB + RotL64(aPrevious, 47U)) + 0xAD2820BCBEB63746ULL;
            aOrbiterF = ((aWandererE + RotL64(aCross, 51U)) + RotL64(aCarry, 57U)) + 0xCCC50759F340A490ULL;
