            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0x53187AF08C0B70C3ULL) + aKeyRotateOrbiterUpdateSaltC[((aIndex + 19U)) & S_SALT1];
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0xB81FCB82BCE56CDFULL;
            aOrbiterB = RotL64((aOrbiterB * 0x2E9B050B1D9BA0CDULL), 5U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterH) + 0x2CA255EB34B4CF41ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x8E0D2F437F21130EULL;
            aOrbiterE = RotL64((aOrbiterE * 0x3DDCAC183A26924BULL), 29U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterG) + 0xACA4131477B24CAFULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterH) ^ 0xA26C8EE0C1D11888ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x08DFC289734B57BDULL), 51U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterI) + 0xC29ECECB03C608FCULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterB) ^ 0x93AF86ED817D3393ULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x8114933D1C2C2F87ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x30FCB6CDED8449E1ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0x3F4334A50926A83BULL) ^ aKeyRotateOrbiterUpdateSaltB[(((31U - aIndex) + 10U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x6FC8CB0AE57DCBB7ULL), 13U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xE36626A5722050B2ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x837DCC9DD9344A6DULL;
            aOrbiterI = RotL64((aOrbiterI * 0x499BD7E8F1391E4BULL), 47U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0xBC1E8BDD645FDF3FULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterA) ^ 0xC3C45D961F7E83C5ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x8A2BF907939837DFULL), 53U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterB) + 0x7E0F7CF97E2B719FULL;
            aOrbiterA = ((aOrbiterA ^ aOrbiterK) ^ 0x7435FAA6D4459A17ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0x47A33E3282F2EC15ULL), 37U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x1845C5A44A8B927EULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterI) ^ 0xE6386407CF0854C4ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xAFAD222A8C8F1CEDULL), 27U);
