            aWandererG = aWandererG + (((RotL64(aPrevious, 43U) + RotL64(aOrbiterK, 29U)) + aOrbiterJ) + aKeyRotateWandererUpdateSaltE[(((31U - aIndex) + 29U)) & S_SALT1]);
