            aWandererC = aWandererC + ((RotL64(aCross, 11U) + aOrbiterH) + RotL64(aOrbiterK, 48U));
            aWandererJ = aWandererJ ^ (((RotL64(aScatter, 21U) + RotL64(aOrbiterF, 41U)) + aOrbiterD) + aKeyRotateWandererUpdateSaltB[((aIndex + 23U)) & S_SALT1]);
