            //
            aCross = (RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 5637U)) & S_BLOCK1], 29U) ^ RotL64(aMagmaLaneA[((S_BLOCK1 - aIndex + 6775U)) & S_BLOCK1], 37U));
            aCross ^= (RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 6202U)) & S_BLOCK1], 14U) ^ RotL64(aPoisonLaneB[((aIndex + 4952U)) & S_BLOCK1], 47U));
            aCross = TwistMix64::DiffuseB(aCross);
            //
            aScatter = (RotL64(aCarry, 27U) ^ RotL64(aIngress, 43U)) + (RotL64(aCross, 5U) ^ RotL64(aPrevious, 56U));
