            //
            aOrbiterA = ((aWandererH + RotL64(aScatter, 53U)) + 0xE1D4FD10B44657D4ULL) + aKeyRotateOrbiterAssignSaltB[(((31U - aIndex) + 15U)) & S_SALT1];
            aOrbiterD = (aWandererI + RotL64(aCross, 39U)) + 0x65ECC7023710E5EFULL;
            aOrbiterG = (aWandererE + RotL64(aPrevious, 20U)) + 0xA8F9FC9F30CB3371ULL;
            aOrbiterH = ((aWandererK + RotL64(aIngress, 13U)) + RotL64(aCarry, 39U)) + 0x0967B4F5057C2B66ULL;
            aOrbiterC = ((aWandererG + RotL64(aScatter, 27U)) + RotL64(aCarry, 51U)) + 0x2C2D5725AA15DE11ULL;
            aOrbiterJ = ((aWandererC + RotL64(aPrevious, 3U)) + RotL64(aCarry, 19U)) + 0xDEB4E674448AE60AULL;
