            aCross = (RotL64(aAetherLaneA[((S_BLOCK1 - aIndex + 9768U)) & S_BLOCK1], 11U) ^ RotL64(aAetherLaneD[((S_BLOCK1 - aIndex + 6047U)) & S_BLOCK1], 22U));
