            aIngress = (RotL64(aFuseLaneA[((aIndex + 8725U)) & S_BLOCK1], 44U) ^ RotL64(aCelestialLaneC[((aIndex + 10667U)) & S_BLOCK1], 23U));
            aIngress ^= (RotL64(aSpiritLaneA[((aIndex + 14360U)) & S_BLOCK1], 35U) ^ RotL64(aKineticLaneA[((aIndex + 14388U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseC(aIngress);
