            aCross ^= (RotL64(aPlasmaLaneC[((S_BLOCK1 - aIndex + 12233U)) & S_BLOCK1], 29U) ^ RotL64(aVaporLaneD[((S_BLOCK1 - aIndex + 12643U)) & S_BLOCK1], 21U));
